129	function extractBalancedJsonObject(text: string) {
130	  for (let start = text.indexOf('{'); start !== -1; start = text.indexOf('{', start + 1)) {
131	    let depth = 0;
132	    let inString = false;
133	    let isEscaped = false;
134	
135	    for (let index = start; index < text.length; index += 1) {
136	      const char = text[index];
137	
138	      if (inString) {
139	        if (isEscaped) {
140	          isEscaped = false;
141	        } else if (char === '\\') {
142	          isEscaped = true;
143	        } else if (char === '"') {
144	          inString = false;
145	        }
146	        continue;
147	      }
148	
149	      if (char === '"') {
150	        inString = true;
151	        continue;
152	      }
153	
154	      if (char === '{') {
155	        depth += 1;
156	        continue;
157	      }
158	
159	      if (char !== '}') {
160	        continue;
161	      }
162	
163	      depth -= 1;
164	      if (depth !== 0) {
165	        continue;
166	      }
167	
168	      const candidate = text.slice(start, index + 1).trim();
169	      try {
170	        const parsed = JSON.parse(candidate) as unknown;
171	        if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
172	          return candidate;
173	        }
174	      } catch {
175	        break;
176	      }
177	      break;
178	    }
179	  }
180	
181	  return null;
182	}
