188	  }
189	
190	  const fenced = /```(?:json)?\s*([\s\S]*?)```/i.exec(trimmed)?.[1];
191	  const normalized = (fenced ?? trimmed).trim();
192	  return extractBalancedJsonObject(normalized) ?? normalized;
