525	  if (!chatUrl) {
526	    return null;
527	  }
528	
529	  const accessToken = await getAgentAccessToken();
530	  const timeout = createTimeoutSignal(TUTOR_TIMEOUT_MS);
531	  try {
532	    const response = await fetch(chatUrl, {
533	      method: 'POST',
534	      headers: {
535	        'Content-Type': 'application/json',
536	        Authorization: `Bearer ${accessToken}`,
537	      },
538	      body: JSON.stringify(buildAgentChatBody(history, options)),
539	      signal: timeout.signal,
540	    });
541	
542	    const text = await response.text();
543	    if (!response.ok) {
544	      throw buildHttpError(response.status, text, `AI Tutor agent failed with HTTP ${response.status}.`);
545	    }
546	
547	    const payload = parseJsonObject(text);
548	    if (!payload || typeof payload.reply !== 'string' || !payload.reply.trim()) {
549	      throw new Error('AI Tutor agent returned an empty response.');
550	    }
551	    return payload.reply.trim();
552	  } catch (error) {
553	    throw normalizeTutorError(error);
554	  } finally {
555	    timeout.cleanup();
556	  }
557	}
