559	function parseSseEvent(block: string) {
560	  const lines = block
561	    .split('\n')
562	    .map((line) => line.trimEnd())
563	    .filter(Boolean);
564	
565	  if (!lines.length) {
566	    return null;
567	  }
568	
569	  let event = 'message';
570	  const dataLines: string[] = [];
571	  for (const line of lines) {
572	    if (line.startsWith('event:')) {
573	      event = line.slice('event:'.length).trim();
574	      continue;
575	    }
576	    if (line.startsWith('data:')) {
577	      dataLines.push(line.slice('data:'.length).trim());
578	    }
579	  }
580	
581	  return {
582	    event,
583	    data: dataLines.join('\n'),
584	  };
585	}
