587	async function requestAgentReplyStream(
588	  history: TutorMessage[],
589	  handlers: TutorReplyStreamHandlers = {},
590	  options: TutorRequestOptions = {},
591	) {
592	  const streamUrl = agentServiceChatStreamUrl();
593	  if (!streamUrl) {
594	    return null;
595	  }
596	
597	  const accessToken = await getAgentAccessToken();
598	  const timeout = createTimeoutSignal(TUTOR_TIMEOUT_MS);
599	  let response: Response;
600	  try {
601	    response = await fetch(streamUrl, {
602	      method: 'POST',
603	      headers: {
604	        'Content-Type': 'application/json',
605	        Authorization: `Bearer ${accessToken}`,
606	      },
607	      body: JSON.stringify(buildAgentChatBody(history, options)),
608	      signal: timeout.signal,
609	    });
610	  } catch (error) {
611	    timeout.cleanup();
612	    throw normalizeTutorError(error);
613	  }
614	
615	  if (!response.ok) {
616	    const text = await response.text();
617	    timeout.cleanup();
618	    throw buildHttpError(response.status, text, `AI Tutor agent failed with HTTP ${response.status}.`);
619	  }
620	
621	  if (!response.body) {
622	    timeout.cleanup();
623	    const reply = await requestAgentReply(history, options);
624	    if (!reply) {
625	      throw new Error('AI Tutor agent did not return a stream.');
626	    }
627	    const payload = { threadId: getTutorThreadId(), reply, usedTools: [] };
628	    handlers.onToken?.(reply);
629	    handlers.onFinal?.(payload);
630	    return payload;
631	  }
632	
633	  const reader = response.body.getReader();
634	  const decoder = new TextDecoder();
635	  let buffer = '';
636	  let reply = '';
637	  let finalPayload: TutorReplyStreamResult | null = null;
638	
639	  try {
640	    while (true) {
641	      const { value, done } = await reader.read();
642	      if (done) {
643	        break;
644	      }
645	
646	      buffer += decoder.decode(value, { stream: true });
647	      buffer = buffer.replace(/\r\n/g, '\n');
648	      let boundary = buffer.indexOf('\n\n');
649	      while (boundary >= 0) {
650	        const rawEvent = buffer.slice(0, boundary);
651	        buffer = buffer.slice(boundary + 2);
652	        boundary = buffer.indexOf('\n\n');
653	
654	        const parsed = parseSseEvent(rawEvent);
655	        if (!parsed?.data) {
656	          continue;
657	        }
658	
659	        const payload = JSON.parse(parsed.data) as {
660	          detail?: string;
661	          reply?: string;
662	          text?: string;
663	          thread_id?: string;
664	          used_tools?: string[];
665	        };
666	
667	        if (parsed.event === 'run_started' && payload.thread_id) {
668	          handlers.onRunStarted?.({ threadId: payload.thread_id });
669	          continue;
670	        }
671	
672	        if (parsed.event === 'token' && payload.text) {
673	          reply += payload.text;
674	          handlers.onToken?.(payload.text);
675	          continue;
676	        }
677	
678	        if (parsed.event === 'final') {
679	          finalPayload = {
680	            threadId: payload.thread_id || getTutorThreadId(),
681	            reply: payload.reply?.trim() || reply.trim(),
682	            usedTools: payload.used_tools ?? [],
683	          };
684	          handlers.onFinal?.(finalPayload);
685	          continue;
686	        }
687	
688	        if (parsed.event === 'error') {
689	          throw normalizeTutorError(new Error(payload.detail || 'AI Tutor agent stream failed.'));
690	        }
691	      }
692	    }
693	  } finally {
694	    timeout.cleanup();
695	    reader.releaseLock();
696	  }
697	
698	  if (!finalPayload) {
699	    finalPayload = {
700	      threadId: getTutorThreadId(),
701	      reply: reply.trim(),
702	      usedTools: [],
703	    };
704	    if (!finalPayload.reply) {
705	      throw new Error('AI Tutor agent stream ended without a reply.');
706	    }
707	    handlers.onFinal?.(finalPayload);
708	  }
709	
710	  return finalPayload;
711	}
