713	async function requestTutorTool<T>(
714	  mode: 'reply' | 'mindmap' | 'quiz',
715	  history: TutorMessage[],
716	  options: TutorRequestOptions = {},
717	) {
718	  if (usesViewerFixtures()) {
719	    if (mode === 'reply') {
720	      return { reply: fixtureReply(history) } as T;
721	    }
722	    if (mode === 'mindmap') {
723	      return {
724	        title: 'Fixture mind map',
725	        nodes: history.slice(-3).map((message, index) => ({
726	          id: `node-${index + 1}`,
727	          label: message.text.slice(0, 40) || `Idea ${index + 1}`,
728	        })),
729	      } as T;
730	    }
731	    if (mode === 'quiz') {
732	      return {
733	        title: 'Fixture quiz',
734	        questions: [
735	          {
736	            prompt: 'What is the main learner workflow?',
737	            options: ['Library -> Course -> Lesson -> Result', 'Builder -> Publish -> Edit'],
738	            answerIndex: 0,
739	          },
740	        ],
741	      } as T;
742	    }
743	  }
744	
745	  if (mode === 'reply' && options.provider !== 'gemini') {
746	    try {
747	      const agentReply = await requestAgentReply(history, options);
748	      if (agentReply) {
749	        return { reply: agentReply } as T;
750	      }
751	    } catch (error) {
752	      if (!shouldFallbackToEdgeFunction(options)) {
753	        throw normalizeTutorError(error);
754	      }
755	    }
756	  }
757	
758	  const apiKeyOverride = getStoredGeminiKey();
759	  if (!rawSupabaseAnonKey) {
760	    throw new Error('AI Tutor requires VITE_SUPABASE_ANON_KEY.');
761	  }
762	
763	  for (let attempt = 1; attempt <= EDGE_REQUEST_MAX_ATTEMPTS; attempt += 1) {
764	    const timeout = createTimeoutSignal(TUTOR_TIMEOUT_MS);
765	    try {
766	      const response = await fetch(tutorFunctionUrl(), {
767	        method: 'POST',
768	        headers: {
769	          'Content-Type': 'application/json',
770	          apikey: rawSupabaseAnonKey,
771	          Authorization: `Bearer ${rawSupabaseAnonKey}`,
772	        },
773	        body: JSON.stringify({
774	          mode,
775	          model: activeModel(options.model),
776	          history,
777	          persona: currentAiTutorPersona(),
778	          allowModelFallback: options.allowModelFallback ?? true,
779	          context: options.context,
780	          apiKeyOverride: apiKeyOverride || undefined,
781	        }),
782	        signal: timeout.signal,
783	      });
784	
785	      const text = await response.text();
786	      const parsed = parseJsonObject(text);
787	      if (!response.ok) {
788	        if (attempt < EDGE_REQUEST_MAX_ATTEMPTS && shouldRetryEdgeFunctionStatus(response.status)) {
789	          await waitForEdgeRetry();
790	          continue;
791	        }
792	        throw buildHttpError(response.status, text, `AI Tutor request failed with HTTP ${response.status}.`);
793	      }
794	      if (!parsed) {
795	        throw new Error('AI Tutor returned invalid JSON.');
796	      }
797	      return parsed as T;
798	    } catch (error) {
799	      if (attempt < EDGE_REQUEST_MAX_ATTEMPTS && shouldRetryEdgeFunctionError(error)) {
800	        await waitForEdgeRetry();
801	        continue;
802	      }
803	      throw normalizeTutorError(error);
804	    } finally {
805	      timeout.cleanup();
806	    }
807	  }
808	
809	  throw new Error('AI Tutor request failed after retry.');
810	}
