1	vi.mock('@/shared/api/supabase', () => ({
2	  supabase: {
3	    auth: {
4	      getSession: vi.fn(async () => ({
5	        data: { session: { access_token: 'demo-access-token' } },
6	        error: null,
7	      })),
8	    },
9	  },
10	}));
11	
12	describe('geminiClient', () => {
13	  afterEach(() => {
14	    vi.unstubAllEnvs();
15	    vi.restoreAllMocks();
16	    vi.resetModules();
17	    window.localStorage.clear();
18	    document.documentElement.lang = '';
19	  });
20	
21	  it('calls the edge function when fixture mode is explicitly disabled in tests', async () => {
22	    vi.stubEnv('VITE_VIEWER_TEST_FIXTURES', '0');
23	    vi.stubEnv('VITE_SUPABASE_URL', 'https://demo-project.supabase.co');
24	    vi.stubEnv('VITE_SUPABASE_ANON_KEY', 'demo-anon-key');
25	    window.localStorage.setItem(
26	      'primoria.viewer.preferences',
27	      JSON.stringify({ language: 'zh-CN', aiTutorPersona: 'socratic' }),
28	    );
29	
30	    const fetchMock = vi.spyOn(globalThis, 'fetch').mockResolvedValue(
31	      new Response(JSON.stringify({ reply: 'Edge reply' }), {
32	        status: 200,
33	        headers: { 'Content-Type': 'application/json' },
34	      }),
35	    );
36	
37	    const { generateTutorReply } = await import('@/shared/api/geminiClient');
38	    const reply = await generateTutorReply([{ role: 'user', text: 'Hello' }]);
39	
40	    expect(reply).toBe('Edge reply');
41	    expect(fetchMock).toHaveBeenCalledWith(
42	      'https://demo-project.functions.supabase.co/viewer-ai-tutor',
43	      expect.objectContaining({
44	        method: 'POST',
45	        headers: expect.objectContaining({
46	          apikey: 'demo-anon-key',
