54	
55	  it('surfaces API error payloads from the edge function', async () => {
56	    vi.stubEnv('VITE_VIEWER_TEST_FIXTURES', '0');
57	    vi.stubEnv('VITE_SUPABASE_URL', 'https://demo-project.supabase.co');
58	    vi.stubEnv('VITE_SUPABASE_ANON_KEY', 'demo-anon-key');
59	
60	    vi.spyOn(globalThis, 'fetch').mockResolvedValue(
61	      new Response(JSON.stringify({ error: 'Tutor quota exceeded.' }), {
62	        status: 429,
63	        headers: { 'Content-Type': 'application/json' },
64	      }),
65	    );
66	
67	    const { generateTutorReply } = await import('@/shared/api/geminiClient');
68	
69	    await expect(generateTutorReply([{ role: 'user', text: 'Hello' }])).rejects.toThrow('Tutor quota exceeded.');
70	  });
71	
72	  it('parses tutor edge responses wrapped in prose and fenced JSON', async () => {
73	    vi.stubEnv('VITE_VIEWER_TEST_FIXTURES', '0');
74	    vi.stubEnv('VITE_SUPABASE_URL', 'https://demo-project.supabase.co');
75	    vi.stubEnv('VITE_SUPABASE_ANON_KEY', 'demo-anon-key');
76	
77	    vi.spyOn(globalThis, 'fetch').mockResolvedValue(
78	      new Response('Here is the JSON you asked for:\n```json\n{"reply":"Edge reply"}\n```\n', {
79	        status: 200,
80	        headers: { 'Content-Type': 'application/json' },
81	      }),
82	    );
83	
84	    const { generateTutorReply } = await import('@/shared/api/geminiClient');
85	    const reply = await generateTutorReply([{ role: 'user', text: 'Hello' }]);
86	
87	    expect(reply).toBe('Edge reply');
88	  });
89	
90	  it('retries the edge function once after a transient service unavailable response', async () => {
91	    vi.stubEnv('VITE_VIEWER_TEST_FIXTURES', '0');
92	    vi.stubEnv('VITE_SUPABASE_URL', 'https://demo-project.supabase.co');
93	    vi.stubEnv('VITE_SUPABASE_ANON_KEY', 'demo-anon-key');
94	
95	    const fetchMock = vi.spyOn(globalThis, 'fetch');
96	    fetchMock
97	      .mockResolvedValueOnce(
98	        new Response(JSON.stringify({ error: 'Temporary outage.' }), {
99	          status: 503,
100	          headers: { 'Content-Type': 'application/json' },
101	        }),
102	      )
103	      .mockResolvedValueOnce(
104	        new Response(JSON.stringify({ reply: 'Recovered edge reply' }), {
105	          status: 200,
106	          headers: { 'Content-Type': 'application/json' },
107	        }),
108	      );
109	
110	    const { generateTutorReply } = await import('@/shared/api/geminiClient');
111	    const reply = await generateTutorReply([{ role: 'user', text: 'Hello' }]);
112	
