128	          new TextEncoder().encode(
129	            [
130	              'event: run_started\n',
131	              'data: {"thread_id":"thread-1"}\n\n',
132	              'event: token\n',
133	              'data: {"text":"Hello "}\n\n',
134	              'event: token\n',
135	              'data: {"text":"world"}\n\n',
136	              'event: final\n',
137	              'data: {"thread_id":"thread-1","reply":"Hello world","used_tools":["recall_user_memories"]}\n\n',
138	            ].join(''),
139	          ),
140	        );
141	        controller.close();
142	      },
143	    });
144	
145	    const fetchMock = vi.spyOn(globalThis, 'fetch').mockResolvedValue(
146	      new Response(streamBody, {
147	        status: 200,
148	        headers: { 'Content-Type': 'text/event-stream' },
149	      }),
150	    );
151	
152	    const { generateTutorReplyStream } = await import('@/shared/api/geminiClient');
153	    const seenTokens: string[] = [];
154	    const result = await generateTutorReplyStream([{ role: 'user', text: 'Hello' }], {
155	      onToken(token) {
156	        seenTokens.push(token);
157	      },
158	    });
159	
160	    expect(result.reply).toBe('Hello world');
161	    expect(result.threadId).toBe('thread-1');
162	    expect(result.usedTools).toEqual(['recall_user_memories']);
163	    expect(seenTokens).toEqual(['Hello ', 'world']);
164	    expect(fetchMock).toHaveBeenCalledWith(
165	      'http://localhost:8787/v1/chat/stream',
166	      expect.objectContaining({
167	        method: 'POST',
