170	        }),
171	      }),
172	    );
173	    expect(JSON.parse(String(fetchMock.mock.calls[0]?.[1]?.body))).toMatchObject({
174	      context: expect.objectContaining({
175	        surface: 'ai-tutor',
176	        locale: 'zh-CN',
177	        ai_tutor_persona: 'coach',
178	      }),
