} from '@/shared/interactive-visual/tutorInteractiveVisuals';
import { VIEWER_PREFERENCES_STORAGE_KEY } from '@/shared/state/preferencesSlice';

const GEMINI_STORAGE_KEY = 'primoria.viewer.gemini-api-key';
